const results = await Promise.allSettled([
tools.exec_command({cmd:"cat .entire/agent-guide.md",max_output_tokens:12000}),
tools.exec_command({cmd:"rg -n 'Complete open-trail|Trail 197|Trail 247|approvalGatePassed|trail watch' /Users/thomi/.codex/memories/MEMORY.md",max_output_tokens:6000})
]);for(let i=0;i<results.length;i++)text({i,result:results[i]});
text(ALL_TOOLS.filter(x=> /trail|graph.*search/i.test(x.name+" "+x.description)).map(x=>({name:x.name,description:x.description.slice(0,180)})));

