const r=await Promise.allSettled([
...[197,241,242,246,251].map(n=>tools.exec_command({cmd:`entire trail show ${n} --json`,max_output_tokens:6000})),
tools.exec_command({cmd:"entire brain search 'memory ladder retrieval safety setup Linear trail review' --json",max_output_tokens:2500}),
tools.exec_command({cmd:"gh pr list --state open --limit 100 --json number,title,headRefName,baseRefName,headRefOid,url,statusCheckRollup,reviewDecision,mergeable",max_output_tokens:12000}),
tools.exec_command({cmd:"git worktree list --porcelain",max_output_tokens:5000})
]);for(let i=0;i<r.length;i++)text({i,result:r[i]});

