	importOK(t, s, 6, r)
	if err := s.Disconnect(project, true); err != nil {
		t.Fatal(err)
	}
	state, _ := s.Load()
	if len(state.RunConflicts) != 0 {
		t.Fatal("purge retained run conflicts", state.RunConflicts)
	}
}
